import { atlasRequest } from '../places.js';
import { createRealm } from './realm.js';
import { showView, clearViewer } from './viewer.js';
const $=s=>document.querySelector(s);let data,memories=[],selected=null,editing=null,currentMemory=null;
const realm=createRealm(selectPlace);
function members(pid){return memories.filter(m=>(data.assignments[m.id]||[]).includes(pid));}
function counts(){return Object.fromEntries(data.places.map(p=>[p.id,members(p.id).length]));}
function render(){const total=memories.filter(m=>(data.assignments[m.id]||[]).length).length;$('#atlas-total').textContent=`${data.places.length} 处地点 · ${total} 段记忆已有归属`;const rail=$('#place-rail');rail.replaceChildren();const numbers=counts();for(const p of data.places){const button=document.createElement('button');button.style.setProperty('--stone',p.color);button.setAttribute('aria-pressed',String(p.id===selected));const gem=document.createElement('span');gem.className='mini-crystal';const text=document.createElement('span'),name=document.createElement('strong'),count=document.createElement('small');name.textContent=p.name;count.textContent=`${numbers[p.id]} 段记忆`;text.append(name,count);button.append(gem,text);button.onclick=()=>selectPlace(p.id);rail.append(button);}realm.setPlaces(data.places,numbers);$('#add-place').disabled=data.places.length>=12;if(selected)renderPanel();}
function selectPlace(id){if(!data)return;selected=id;document.body.classList.add('has-place');$('#place-panel').hidden=false;renderPanel();realm.focus(id);$('#close-place').focus({preventScroll:true});}
function renderPanel(){const p=data.places.find(p=>p.id===selected);if(!p)return;const panel=$('#place-panel');panel.style.setProperty('--stone',p.color);$('#place-name').textContent=p.name;const list=members(p.id);$('#place-count').textContent=`${list.length} 段属于这里的记忆`;$('#place-rail').querySelectorAll('button').forEach((b,i)=>b.setAttribute('aria-pressed',String(data.places[i].id===selected)));const host=$('#place-memories');host.replaceChildren();
 if(!list.length){const empty=document.createElement('div');empty.className='empty-memory';const star=document.createElement('span');star.textContent='✧';const h=document.createElement('h3');h.textContent='这里，等待第一段记忆';const p=document.createElement('p');p.textContent='在第一章打开一段回忆，点「为记忆标记地点」，把它交给这颗魔法石。';const a=document.createElement('a');a.href='/';a.textContent='回到第一章，收藏记忆 ↗';empty.append(star,h,p,a);host.append(empty);return;}
 for(const m of list){const button=document.createElement('button');button.className='memory-card';const img=new Image();img.src=m.photo_url;img.alt='';img.loading='lazy';const text=document.createElement('span'),name=document.createElement('strong'),kind=document.createElement('small');name.textContent=m.name;kind.textContent=m.status==='ready'?(m.mode==='world'?'空间记忆 · 点击进入':'立体物件 · 点击查看'):'原片记忆 · 点击查看';text.append(name,kind);button.append(img,text);button.onclick=()=>openMemory(m);host.append(button);}}
function closePlace(){selected=null;$('#place-panel').hidden=true;document.body.classList.remove('has-place');$('#place-rail').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed','false'));realm.focus(null);$('#overview').focus({preventScroll:true});}
$('#close-place').onclick=closePlace;$('#overview').onclick=closePlace;
function editor(place=null){editing=place?.id||null;$('#editor-title').textContent=place?'编辑这处地点':'点亮一个新地点';$('#place-input').value=place?.name||'';$('#color-input').value=place?.color||'#a69aff';$('#editor-error').textContent='';$('#place-editor').showModal();realm.setPaused(true);$('#place-input').focus();}
$('#add-place').onclick=()=>editor();$('#edit-place').onclick=()=>editor(data.places.find(p=>p.id===selected));$('#cancel-editor').onclick=()=>$('#place-editor').close();$('#place-editor').addEventListener('close',()=>realm.setPaused(false));
$('#place-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{data=await atlasRequest({action:'place',id:editing,name:$('#place-input').value.trim(),color:$('#color-input').value});render();$('#place-editor').close();if(selected)realm.focus(selected);}catch(error){$('#editor-error').textContent=error.message;}finally{button.disabled=false;}};
function openMemory(m){currentMemory=m;$('#viewer-name').textContent=m.name;$('#view-3d').hidden=!(m.status==='ready'&&(m.model_url||m.world_assets?.splat_url));$('#memory-dialog').showModal();realm.setPaused(true);showView(m,$('#view-3d').hidden?'photo':'3d');}
$('#close-memory').onclick=()=>$('#memory-dialog').close();$('#memory-dialog').addEventListener('close',()=>{clearViewer();realm.setPaused(false);});$('#view-photo').onclick=()=>showView(currentMemory,'photo');$('#view-3d').onclick=()=>showView(currentMemory,'3d');addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')&&selected)closePlace();});
async function load(){try{const [atlas,response]=await Promise.all([atlasRequest(),fetch('/api/memories')]);if(!response.ok)throw Error('记忆服务暂未连接');const result=await response.json();data=atlas;memories=[...result.items.filter(m=>m.mode!=='fourview'),...atlas.archives];render();$('#atlas-status').textContent='';}catch(e){$('#atlas-status').textContent=e.message;$('#atlas-total').textContent='暂时无法读取记忆，请刷新重试';}}
load();addEventListener('pageshow',e=>{if(e.persisted)load();});
